// Concatenates every migration plus the demo seed into supabase/setup.sql, so the whole
// database can be created by pasting ONE file into the Supabase SQL Editor.
import { readdirSync, readFileSync, writeFileSync } from 'node:fs';
import { join } from 'node:path';

const dir = join(import.meta.dirname, '..', 'supabase');
const migrations = readdirSync(join(dir, 'migrations'))
  .filter((f) => f.endsWith('.sql'))
  .sort();
const parts = [
  '-- GUTECH LMS - complete database setup (generated by `npm run db:bundle`; do not edit).',
  '-- Paste this whole file into Supabase -> SQL Editor -> Run. Run it ONCE on an empty project.',
  ...migrations.map(
    (f) => `\n-- ===== migrations/${f} =====\n${readFileSync(join(dir, 'migrations', f), 'utf8')}`,
  ),
  `\n-- ===== seed.sql (demo data) =====\n${readFileSync(join(dir, 'seed.sql'), 'utf8')}`,
];
writeFileSync(join(dir, 'setup.sql'), parts.join('\n'));
console.log(`supabase/setup.sql written (${migrations.length} migrations + seed)`);
